/* 2 — Normalize   (BUILD_SPEC §6a)
 *
 * The coach frontend POSTs the roster.json shape. A browser only skips the CORS
 * preflight for a "simple" content type, so the form sends text/plain and the
 * body lands here as a string; an application/json POST (curl, Postman, the
 * Veo pull node at Rung 3) arrives already parsed. Accept both.
 *
 * ── The only two values to edit when moving off the mock ──────────────────
 * CV_SERVICE_URL  the §6b service. Swap for the Modal/RunPod endpoint at
 *                 Rung 3 — the contract does not change, so nothing else does.
 * SUPABASE_URL    the project REST root. Not a secret; the service key lives
 *                 in the n8n credential store, never in this workflow.
 */
const CV_SERVICE_URL = 'https://shaneesilva--footage-to-tactics-cv-web.modal.run';
const SUPABASE_URL = 'https://tifynfruqgkbuiyiljfb.supabase.co';

const crypto = require('crypto');

// SHA-256 of the club access code. The frontend is a static page and this
// workflow is exported to a public repo, so neither can hold a secret: the coach
// types the code, and only its hash lives here. A leaked hash of a 28-character
// random code does not give the code back. Regenerate both together.
const CLUB_ACCESS_SHA256 = '8469c4947aed78b64d17eec23532b447ca201d972ec908f7b1e09f02bd565de4';

const req = $input.first().json;
let body = req.body ?? req;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (e) {
    throw new Error('Submitted body is not valid JSON: ' + e.message);
  }
}

// Every submission spends Claude calls and writes to the database, so it has to
// come from someone holding the club's code. Compared in constant time.
const supplied = typeof body.access_code === 'string' ? body.access_code : '';
const digest = crypto.createHash('sha256').update(supplied, 'utf8').digest();
if (!supplied || !crypto.timingSafeEqual(digest, Buffer.from(CLUB_ACCESS_SHA256, 'hex'))) {
  throw new Error('Access code missing or incorrect — submission rejected.');
}

const players = Array.isArray(body.players) ? body.players : [];
if (!players.length) {
  throw new Error('No players in the submitted roster — there is nothing to analyse.');
}

return [{
  json: {
    // Minted here, never taken from the request. The report endpoints are keyed
    // by match_id alone, so a timestamp id (or a client-chosen one) lets anyone
    // walk other clubs' reports — player names, ages, ratings.
    match_id: 'm_' + crypto.randomBytes(12).toString('hex'),
    club_id: body.club_id || 'c_001',
    club_name: typeof body.club_name === 'string' && body.club_name.trim() ? body.club_name.trim() : null,
    opponent: body.opponent || 'Unknown opponent',
    date: body.date || new Date().toISOString().slice(0, 10),
    footage_url: body.footage_url || null,
    // Which side of the camera view the coach's team defends. The CV can split
    // the two teams but not tell which is ours; see cv-service _home_side.
    home_side: body.home_side === 'left' || body.home_side === 'right' ? body.home_side : null,
    coach_notes: body.coach_notes || '',
    playing_style: body.playing_style || '',
    players,
    manual_stats: Array.isArray(body.manual_stats) ? body.manual_stats : [],
    cv_service_url: CV_SERVICE_URL,
    supabase_url: SUPABASE_URL,
    submitted_at: new Date().toISOString(),
  },
}];

/* 5a — input 1 of the Merge: one item per squad player.
 *
 * The roster entry and the manual stats the coach typed both arrive inside the
 * same form submission, so joining them needs no Merge node — the Merge exists
 * for the join that genuinely spans two systems, CV against the squad.
 */
const m = $input.first().json;
const stats = Object.fromEntries((m.manual_stats || []).map((s) => [s.player_id, s]));

// Blank boxes on the form arrive as '' and must stay null, not become 0:
// "no shots faced" and "0 shots faced" are different claims to put in front of
// the analyst.
const n = (v) => (v === '' || v === undefined || v === null ? null : Number(v));
const z = (v) => n(v) ?? 0;

return (m.players || []).map((p) => ({
  json: {
    player_id: p.player_id,
    name: p.name,
    jersey_number: n(p.jersey_number),
    position: p.position,
    strong_foot: p.strong_foot ?? null,
    age: n(p.age),
    height_cm: n(p.height_cm),
    goals: z(stats[p.player_id]?.goals),
    assists: z(stats[p.player_id]?.assists),
    shots: z(stats[p.player_id]?.shots),
    shots_on_target: z(stats[p.player_id]?.shots_on_target),
    tackles: z(stats[p.player_id]?.tackles),
    tackles_won: z(stats[p.player_id]?.tackles_won),
    fouls: z(stats[p.player_id]?.fouls),
    yellow: z(stats[p.player_id]?.yellow),
    red: z(stats[p.player_id]?.red),
    saves: n(stats[p.player_id]?.saves),
    shots_faced: n(stats[p.player_id]?.shots_faced),
  },
}));

/* 5b — input 2 of the Merge: one item per tracked player.
 *
 * Reached from BOTH branches — the polling loop's success output and node 4b's
 * degraded output — so this is where the two paths become one shape again.
 *
 * It always emits at least one item. A Merge input that receives zero items
 * leaves the branch with nothing to execute, and the run would never reach
 * Claude: exactly the hang that 4b exists to prevent. The sentinel below
 * matches no player_id, so "Enrich Input 1" drops it and every squad player
 * still comes through with CV fields simply absent.
 */
const src = $input.first().json;
const players = Array.isArray(src.players) ? src.players : [];

const rows = players
  // Tracks that could not be resolved to a shirt carry player_id null (§7a).
  // They are real data — they feed team shape — but they belong to nobody, so
  // they must not be joined onto a squad row.
  .filter((p) => p && p.player_id)
  .map((p) => ({
    json: {
      player_id: p.player_id,
      track_id: p.track_id ?? null,
      cv_jersey_number: p.jersey_number ?? null,
      id_confidence: p.id_confidence ?? null,
      heatmap_url: p.heatmap_url ?? null,
      distance_m: p.distance_m ?? null,
      top_speed_kmh: p.top_speed_kmh ?? null,
      avg_x: p.avg_position?.x ?? null,
      avg_y: p.avg_position?.y ?? null,
      zone_share: p.zone_share ?? null,
      minutes_tracked: p.minutes_tracked ?? null,
    },
  }));

return rows.length ? rows : [{ json: { player_id: '__no_cv__' } }];

/* 6 — Build profile   (BUILD_SPEC §10b)
 *
 * In:  the merged per-player rows.
 * Out: ONE item holding the whole match profile, plus the user message that
 *      node 8 hands to Claude.
 */
const rows = $input.all().map((i) => i.json).filter((r) => r.player_id !== '__no_cv__');
const m = $('2 Normalize').first().json;

// The CV payload as the service returned it. The polling node does not execute
// on the degraded branch, so referencing it has to be guarded — n8n throws when
// you ask for a node that never ran.
let cv = null;
try {
  const last = $('4 Get CV result').first().json;
  if (last && last.status === 'done' && Array.isArray(last.players)) cv = last;
} catch (e) { /* CV branch never ran */ }

let cvError = null;
if (!cv) {
  try { cvError = $('4b CV unavailable').first().json.cv_error; } catch (e) { cvError = 'CV data unavailable'; }
}
const degraded = !cv;

const r1 = (v) => (v == null ? null : Math.round(v * 10) / 10);
const pct = (a, b) => (a == null || !b ? null : Math.round((a / b) * 1000) / 10);

const players = rows.map((r) => ({
  player_id: r.player_id,
  name: r.name,
  jersey_number: r.jersey_number,
  position: r.position,
  strong_foot: r.strong_foot,
  age: r.age,
  height_cm: r.height_cm,
  manual: {
    goals: r.goals, assists: r.assists, shots: r.shots, shots_on_target: r.shots_on_target,
    tackles: r.tackles, tackles_won: r.tackles_won, fouls: r.fouls,
    yellow: r.yellow, red: r.red, saves: r.saves, shots_faced: r.shots_faced,
  },
  derived: {
    shot_conversion_pct: pct(r.goals, r.shots),
    shot_accuracy_pct: pct(r.shots_on_target, r.shots),
    tackle_success_pct: pct(r.tackles_won, r.tackles),
    save_pct: pct(r.saves, r.shots_faced),
    goal_contributions: (r.goals || 0) + (r.assists || 0),
  },
  // Absent, not zeroed. A distance of null reads as "we did not measure this";
  // a distance of 0 reads as "he did not move", and the analyst would believe it.
  spatial: r.distance_m == null && r.avg_x == null ? null : {
    heatmap_url: r.heatmap_url ?? null,
    distance_m: r.distance_m ?? null,
    top_speed_kmh: r.top_speed_kmh ?? null,
    avg_position: r.avg_x == null ? null : { x: r.avg_x, y: r.avg_y },
    zone_share: r.zone_share ?? null,
    id_confidence: r.id_confidence ?? null,
    minutes_tracked: r.minutes_tracked ?? null,
  },
}));

const sum = (f) => players.reduce((a, p) => a + (f(p) || 0), 0);
const tracked = players.filter((p) => p.spatial && p.spatial.distance_m != null);

const team = {
  goals: sum((p) => p.manual.goals),
  assists: sum((p) => p.manual.assists),
  shots: sum((p) => p.manual.shots),
  shots_on_target: sum((p) => p.manual.shots_on_target),
  shot_conversion_pct: pct(sum((p) => p.manual.goals), sum((p) => p.manual.shots)),
  tackles: sum((p) => p.manual.tackles),
  tackles_won: sum((p) => p.manual.tackles_won),
  tackle_success_pct: pct(sum((p) => p.manual.tackles_won), sum((p) => p.manual.tackles)),
  fouls: sum((p) => p.manual.fouls),
  yellow: sum((p) => p.manual.yellow),
  red: sum((p) => p.manual.red),
  squad_size: players.length,
  players_tracked: tracked.length,
  total_distance_m: tracked.length ? r1(tracked.reduce((a, p) => a + p.spatial.distance_m, 0)) : null,
  mean_distance_m: tracked.length ? r1(tracked.reduce((a, p) => a + p.spatial.distance_m, 0) / tracked.length) : null,
  peak_speed_kmh: tracked.length ? r1(Math.max(...tracked.map((p) => p.spatial.top_speed_kmh || 0))) : null,
  shape: cv?.team_shape?.home ?? null,
  // Named, not hidden. §7a: where identity is shaky the analyst is told so and
  // is expected to lean on the manual stats instead.
  low_confidence_players: players
    .filter((p) => p.spatial && p.spatial.id_confidence != null && p.spatial.id_confidence < 0.75)
    .map((p) => `${p.name} (${p.spatial.id_confidence})`),
  unresolved_tracks: cv ? cv.players.filter((p) => !p.player_id).length : 0,
};

/* ── the §10b user message ─────────────────────────────────────────────── */
const f = (v, d = 1) => (v == null ? '—' : Number(v).toFixed(d));
const pc = (v) => (v == null ? 'n/a' : Number(v).toFixed(1) + '%');
const L = [];
L.push(`MATCH: ${m.opponent} on ${m.date}`);
L.push(`COACH NOTES: ${m.coach_notes || 'none given'}`);
L.push(`PREFERRED STYLE: ${m.playing_style || 'not specified'}`);
L.push('');

if (degraded) {
  L.push(`DATA QUALITY: computer vision did NOT complete for this match (${cvError}).`);
  L.push('There is no spatial data at all. Base the analysis on the manual stats and the');
  L.push('coach notes, and say plainly in the summaries where a spatial read would have');
  L.push('been needed to judge something. Do not infer positioning, distance or workrate.');
} else {
  L.push(`DATA QUALITY: ${team.players_tracked}/${team.squad_size} players tracked over a ` +
         `${cv.clip?.duration_s ?? '?'} s clip at ${cv.clip?.fps_processed ?? '?'} fps.`);
  if (team.unresolved_tracks) {
    L.push(`${team.unresolved_tracks} track(s) could not be matched to a shirt and were used for team shape only.`);
  }
  if (team.low_confidence_players.length) {
    L.push(`Low identity confidence (<0.75), treat their spatial data with caution: ${team.low_confidence_players.join(', ')}.`);
  }
}
L.push('');

L.push(`TEAM TOTALS: goals ${team.goals}, assists ${team.assists}, shots ${team.shots} ` +
       `(${team.shots_on_target} on target, conversion ${pc(team.shot_conversion_pct)}), ` +
       `tackles ${team.tackles_won}/${team.tackles} (${pc(team.tackle_success_pct)}), ` +
       `fouls ${team.fouls}, cards ${team.yellow}Y ${team.red}R`);
L.push(team.shape
  ? `TEAM SHAPE: compactness ${f(team.shape.compactness_m)} m, width ${f(team.shape.width_m)} m, ` +
    `defensive line height ${f(team.shape.line_height_m)} m (pitch is 105 x 68 m, attacking left to right)`
  : 'TEAM SHAPE: not available (no CV data)');
L.push(`TEAM RUNNING: ${team.total_distance_m == null ? 'not available' :
  `${f(team.total_distance_m)} m total, ${f(team.mean_distance_m)} m mean, peak speed ${f(team.peak_speed_kmh)} km/h`}`);
L.push('');

L.push('PLAYERS:');
for (const p of players) {
  const d = p.derived;
  const s = p.spatial;
  L.push(`- ${p.name} (#${p.jersey_number}, ${p.position}, ${p.strong_foot || '?'} foot, player_id ${p.player_id}` +
         `${s && s.id_confidence != null ? `, id_conf ${f(s.id_confidence, 2)}` : ''})`);
  L.push(`  manual: goals ${p.manual.goals}, assists ${p.manual.assists}, ` +
         `shots ${p.manual.shots} (${p.manual.shots_on_target} OT), ` +
         `tackles ${p.manual.tackles_won}/${p.manual.tackles}, fouls ${p.manual.fouls}, ` +
         `cards ${p.manual.yellow}Y ${p.manual.red}R, ` +
         `saves ${p.manual.saves == null ? '—' : p.manual.saves}/${p.manual.shots_faced == null ? '—' : p.manual.shots_faced}`);
  L.push(`  derived: conversion ${pc(d.shot_conversion_pct)}, accuracy ${pc(d.shot_accuracy_pct)}, ` +
         `tackle success ${pc(d.tackle_success_pct)}, save rate ${pc(d.save_pct)}`);
  L.push(s
    ? `  spatial: distance ${f(s.distance_m)} m, top speed ${f(s.top_speed_kmh)} km/h, ` +
      `avg pos (${f(s.avg_position?.x)}, ${f(s.avg_position?.y)}), ` +
      `zones def/mid/att ${f(s.zone_share?.def_third, 2)}/${f(s.zone_share?.mid_third, 2)}/${f(s.zone_share?.att_third, 2)}`
    : '  spatial: none (CV unavailable)');
}
L.push('');
L.push(`Produce the analysis for all ${players.length} players, using exactly these player_id values.`);
L.push('Return it as JSON matching the schema.');

return [{
  json: {
    match_id: m.match_id,
    club_id: m.club_id,
    opponent: m.opponent,
    date: m.date,
    footage_url: m.footage_url,
    coach_notes: m.coach_notes,
    playing_style: m.playing_style,
    supabase_url: m.supabase_url,
    degraded,
    cv_error: cvError,
    clip: cv?.clip ?? null,
    team,
    players,
    // Handed back to the frontend as-is so it can draw the heatmaps and show
    // how many tracks went unresolved.
    cv: cv ? { clip: cv.clip, players: cv.players, team_shape: cv.team_shape } : null,

    // One shared header, then two kinds of prompt built from it. Asking for the
    // whole 11-player report in a single call produced ~5,000 tokens over ~5
    // minutes and JSON that would not parse; small calls parse, and they run in
    // parallel.
    context_header: L.join('\n'),
    team_prompt: L.join('\n') + '\n\nReturn ONLY the team-level JSON object.',
    claude_user_message: L.join('\n'),
  },
}];

/* 6b — one item per player, each carrying its own small prompt.
 *
 * The single-call version asked for all eleven players at once: ~5,000 output
 * tokens, ~5 minutes, and JSON that failed to parse three runs in a row. These
 * items feed a chain with Batch Size 5, so the calls run a few at a time and
 * each one is small enough to come back whole.
 *
 * A player whose JSON is malformed now costs one card, not the whole report.
 */
// Read the profile by name. $input here is the team call's output, because this
// node sits downstream of it to keep the two analyst calls in a single chain.
const m = $('6 Build profile').first().json;
const f = (v, d = 1) => (v == null ? '—' : Number(v).toFixed(d));
const pc = (v) => (v == null ? 'n/a' : Number(v).toFixed(1) + '%');

return m.players.map((p) => {
  const d = p.derived;
  const s = p.spatial;
  const L = [];
  L.push(`MATCH: ${m.opponent} on ${m.date}`);
  L.push(`COACH NOTES: ${m.coach_notes || 'none given'}`);
  L.push(`PREFERRED STYLE: ${m.playing_style || 'not specified'}`);
  if (m.degraded) {
    L.push('DATA QUALITY: no computer-vision data for this match. Use the manual stats and');
    L.push('the coach notes only. Do not infer positioning, distance or workrate.');
  }
  L.push('');
  L.push(`PLAYER: ${p.name}, #${p.jersey_number}, ${p.position}, ${p.strong_foot || '?'} foot, player_id ${p.player_id}`);
  L.push(`manual: goals ${p.manual.goals}, assists ${p.manual.assists}, ` +
         `shots ${p.manual.shots} (${p.manual.shots_on_target} on target), ` +
         `tackles ${p.manual.tackles_won}/${p.manual.tackles}, fouls ${p.manual.fouls}, ` +
         `cards ${p.manual.yellow}Y ${p.manual.red}R, ` +
         `saves ${p.manual.saves == null ? '—' : p.manual.saves}/${p.manual.shots_faced == null ? '—' : p.manual.shots_faced}`);
  L.push(`derived: conversion ${pc(d.shot_conversion_pct)}, accuracy ${pc(d.shot_accuracy_pct)}, ` +
         `tackle success ${pc(d.tackle_success_pct)}, save rate ${pc(d.save_pct)}`);
  L.push(s
    ? `spatial: distance ${f(s.distance_m)} m, top speed ${f(s.top_speed_kmh)} km/h, ` +
      `avg pos (${f(s.avg_position?.x)}, ${f(s.avg_position?.y)}), ` +
      `zones def/mid/att ${f(s.zone_share?.def_third, 2)}/${f(s.zone_share?.mid_third, 2)}/${f(s.zone_share?.att_third, 2)}` +
      (s.id_confidence != null ? `, identity confidence ${f(s.id_confidence, 2)}` : '')
    : 'spatial: none (CV unavailable)');
  if (m.team.shape) {
    L.push(`TEAM SHAPE for context: compactness ${f(m.team.shape.compactness_m)} m, ` +
           `width ${f(m.team.shape.width_m)} m, line height ${f(m.team.shape.line_height_m)} m`);
  }
  L.push('');
  L.push(`Analyse this one player. Return ONLY the JSON object for player_id "${p.player_id}".`);

  return { json: { player_id: p.player_id, name: p.name, player_prompt: L.join('\n') } };
});

/* 11 — Check, cache and render
 *
 * Three jobs:
 *  1. repair the two things that go wrong with a generated report — a best XI
 *     that is not eleven names, and a players[] that quietly drops somebody;
 *  2. cache the finished report in workflow static data, which is what the
 *     /report endpoint serves back to the coach frontend;
 *  3. render a self-contained HTML report, served at /report-html.
 */
const profile = $('6 Build profile').first().json;
const squad = profile.players;
const byId = Object.fromEntries(squad.map((p) => [p.player_id, p]));

/* Parse the model's text ourselves rather than leaning on the Structured Output
 * Parser. Three live runs failed with "Invalid JSON in model output" and took
 * the whole execution down with them; here a fence, a preamble or one ragged
 * response costs at most a single card. */
function extractJson(v) {
  if (v && typeof v === 'object') return v;
  let t = String(v ?? '').trim();
  if (!t) return null;
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) t = fence[1].trim();
  const a = t.indexOf('{');
  if (a === -1) return null;
  t = t.slice(a);

  // Gather every reading that parses, then keep the richest one. Stopping at
  // the first balanced brace is not safe: a model that closes a nested object
  // one key early leaves a stray '}' mid-reply, and the prefix ending there is
  // perfectly valid JSON that silently drops everything after it. That cost us
  // the tactics block on a run where the reply was otherwise complete.
  const cands = [];
  const tryPush = (str) => {
    try {
      const o = JSON.parse(str);
      if (o && typeof o === 'object' && !Array.isArray(o)) cands.push(o);
    } catch (e) { /* not a reading */ }
  };

  tryPush(t);

  const scan = (fn) => {
    let depth = 0, inStr = false, esc = false;
    for (let i = 0; i < t.length; i++) {
      const c = t[i];
      if (esc) { esc = false; fn(c, i, depth, true); continue; }
      if (c === '\\') { esc = true; fn(c, i, depth, true); continue; }
      if (c === '"') { inStr = !inStr; fn(c, i, depth, true); continue; }
      if (inStr) { fn(c, i, depth, true); continue; }
      if (c === '{') depth++;
      else if (c === '}') depth--;
      fn(c, i, depth, false);
    }
    return depth;
  };

  // every point where the braces balance is a candidate ending
  scan((c, i, depth, inStr) => {
    if (!inStr && c === '}' && depth <= 0) tryPush(t.slice(0, i + 1));
  });

  // and one repaired reading, dropping closers that would end the object while
  // more fields plainly follow
  let repaired = '', d = 0, inStr2 = false, esc2 = false;
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (esc2) { repaired += c; esc2 = false; continue; }
    if (c === '\\') { repaired += c; esc2 = true; continue; }
    if (c === '"') { inStr2 = !inStr2; repaired += c; continue; }
    if (!inStr2) {
      if (c === '{') d++;
      else if (c === '}') {
        if (d <= 1 && t.slice(i + 1).replace(/\s+/g, '').startsWith(',"')) continue;
        d--;
      }
    }
    repaired += c;
  }
  while (d-- > 0) repaired += '}';
  tryPush(repaired);

  if (!cands.length) return null;
  return cands.sort((x, y) => Object.keys(y).length - Object.keys(x).length)[0];
}
const textOf = (j) => (j == null ? null : (j.text ?? j.output ?? j.response ?? j));

// The team call is a separate node; guard it so a failure there still leaves
// eleven player cards standing.
let teamRaw = {};
try { teamRaw = extractJson(textOf($('8b Ask Claude - team').first().json)) || {}; } catch (e) { teamRaw = {}; }

// One item per player, in the same order 6b emitted them, so a response that
// forgets its own player_id can still be placed by position.
let order = [];
try { order = $('6b Player prompts').all().map((i) => i.json.player_id); } catch (e) { /* ignore */ }

const parsedPlayers = [];
$input.all().forEach((item, i) => {
  const parsed = extractJson(textOf(item.json));
  if (!parsed) return;
  const pid = byId[parsed.player_id] ? parsed.player_id : order[i];
  if (pid && byId[pid]) parsedPlayers.push({ ...parsed, player_id: pid });
});

const out = { team: teamRaw, players: parsedPlayers };

/* ── players ──────────────────────────────────────────────────────────── */
const swot = (s) => ({
  strengths: Array.isArray(s?.strengths) ? s.strengths : [],
  weaknesses: Array.isArray(s?.weaknesses) ? s.weaknesses : [],
  opportunities: Array.isArray(s?.opportunities) ? s.opportunities : [],
  threats: Array.isArray(s?.threats) ? s.threats : [],
});

const returned = Object.fromEntries(
  (Array.isArray(out.players) ? out.players : []).filter((p) => p && byId[p.player_id]).map((p) => [p.player_id, p]));

const players = squad.map((sq) => {
  const p = returned[sq.player_id];
  if (!p) {
    // Say so rather than inventing one. A missing card is visible; a fabricated
    // one is not.
    return {
      player_id: sq.player_id, rating: null,
      swot: swot(null), summary: 'No analysis was returned for this player.',
      training_plan: [],
    };
  }
  const r = Number(p.rating);
  return {
    player_id: sq.player_id,
    rating: Number.isFinite(r) ? Math.round(Math.min(10, Math.max(0, r)) * 10) / 10 : null,
    swot: swot(p.swot),
    summary: typeof p.summary === 'string' ? p.summary : '',
    training_plan: (Array.isArray(p.training_plan) ? p.training_plan : [])
      .filter((d) => d && (d.focus || d.drill))
      .map((d) => ({ focus: d.focus || '', drill: d.drill || '', why: d.why || '' })),
  };
});

/* ── team ─────────────────────────────────────────────────────────────── */
const t = out.team || {};
const rank = players.slice().sort((a, b) => (b.rating ?? -1) - (a.rating ?? -1));

const seen = new Set();
let xi = (Array.isArray(t.best_xi) ? t.best_xi : [])
  .filter((s) => s && byId[s.player_id] && !seen.has(s.player_id) && seen.add(s.player_id))
  .map((s) => ({ player_id: s.player_id, position: s.position || byId[s.player_id].position }));

// Top up from the highest-rated players still unpicked, in their own listed
// position, until there are eleven — or until the squad runs out.
for (const p of rank) {
  if (xi.length >= 11) break;
  if (seen.has(p.player_id)) continue;
  seen.add(p.player_id);
  xi.push({ player_id: p.player_id, position: byId[p.player_id].position });
}
xi = xi.slice(0, 11);

// A model that closes team_swot early leaves opportunities and threats sitting
// at the top level. Take them from wherever they landed rather than showing the
// coach two empty columns.
const tsRaw = { ...(t.team_swot || {}) };
for (const k of ['strengths', 'weaknesses', 'opportunities', 'threats']) {
  if (!Array.isArray(tsRaw[k]) && Array.isArray(t[k])) tsRaw[k] = t[k];
}

const team = {
  formation: typeof t.formation === 'string' && t.formation ? t.formation : '4-3-3',
  best_xi: xi,
  team_swot: swot(tsRaw),
  position_weaknesses: (Array.isArray(t.position_weaknesses) ? t.position_weaknesses : [])
    .filter((w) => w && (w.area || w.issue))
    .map((w) => ({ area: w.area || '', issue: w.issue || '' })),
  playing_style_note: typeof t.playing_style_note === 'string' ? t.playing_style_note : '',
  // How the side should actually set up for the style the coach picked.
  tactics: t.tactics && typeof t.tactics === 'object'
    ? Object.fromEntries(Object.entries(t.tactics)
        .filter(([, v]) => typeof v === 'string' && v.trim())
        .map(([k, v]) => [k, v.trim()]))
    : null,
};

/* ── the HTML fallback report ─────────────────────────────────────────── */
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const li = (xs) => (xs.length ? `<ul>${xs.map((x) => `<li>${esc(x)}</li>`).join('')}</ul>` : '<p class="none">—</p>');
const fmt = (v, d = 0) => (v == null ? '—' : Number(v).toFixed(d));

const swotHtml = (s) => ['strengths', 'weaknesses', 'opportunities', 'threats']
  .map((k) => `<div class="sw ${k[0]}"><h4>${k}</h4>${li(s[k])}</div>`).join('');

const cards = players.slice().sort((a, b) => (b.rating ?? -1) - (a.rating ?? -1)).map((p) => {
  const sq = byId[p.player_id];
  const sp = sq.spatial;
  const rc = p.rating == null ? '' : p.rating >= 7.5 ? 'hi' : p.rating >= 6.5 ? 'mid' : 'lo';
  const stats = [
    [sq.manual.goals, 'goals'], [sq.manual.assists, 'assists'],
    [sp ? fmt(sp.distance_m) + ' m' : '—', 'distance'],
    [sp ? fmt(sp.top_speed_kmh, 1) : '—', 'km/h'],
  ].map(([v, l]) => `<div><b>${esc(v)}</b><span>${l}</span></div>`).join('');
  const plan = p.training_plan.map((d) =>
    `<div class="drill"><b>${esc(d.focus)}</b> — ${esc(d.drill)}${d.why ? `<em>${esc(d.why)}</em>` : ''}</div>`).join('');
  return `<article class="card">
  <header><span class="shirt">${esc(sq.jersey_number)}</span>
    <span class="who"><b>${esc(sq.name)}</b><small>${esc(sq.position)} · ${esc(sq.strong_foot || '?')} foot${
      sp && sp.id_confidence != null ? ` · ID ${Math.round(sp.id_confidence * 100)}%` : ''}</small></span>
    <span class="rating ${rc}">${p.rating == null ? '—' : p.rating.toFixed(1)}</span></header>
  ${sp && sp.heatmap_url ? `<img class="hm" src="${esc(sp.heatmap_url)}" alt="Heatmap for ${esc(sq.name)}" loading="lazy">` : ''}
  <div class="stats">${stats}</div>
  <p class="sum">${esc(p.summary)}</p>
  <div class="swot">${swotHtml(p.swot)}</div>
  ${plan ? `<div class="plan"><h4>Training plan</h4>${plan}</div>` : ''}
</article>`;
}).join('');

const banner = profile.degraded
  ? `<p class="banner">⚠ Computer vision did not complete for this match (${esc(profile.cv_error)}). Spatial data is missing; everything below rests on the manual stats and the coach's notes.</p>`
  : profile.team.unresolved_tracks
    ? `<p class="note">${profile.team.unresolved_tracks} track(s) could not be matched to a shirt number and were used for team shape only.</p>`
    : '';

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(profile.opponent)} · ${esc(profile.date)} — match report</title>
<style>
