h2{font-size:1.05rem;margin:0 0 12px;letter-spacing:.02em;text-transform:uppercase;color:#8ba0ae}
.swot{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.sw h4{margin:0 0 5px;font-size:.72rem;text-transform:uppercase;letter-spacing:.08em;color:#8ba0ae}
.sw{border-left:3px solid #2c3f4c;padding-left:10px}
.sw.s{border-color:#2fbf71}.sw.w{border-color:#d6402a}.sw.o{border-color:#4ea3e0}.sw.t{border-color:#e0a33e}
