</style></head><body><div class="wrap">
<h1>${esc(profile.opponent)}</h1>
<p class="sub">${esc(profile.date)} · match ${esc(profile.match_id)}</p>
${banner}
<div class="panel">
  <h2>Team</h2>
  <p><span class="badge">${esc(team.formation)}</span>${esc(team.playing_style_note)}</p>
  <div class="xi">${team.best_xi.map((s) => `<div><b>${esc(byId[s.player_id]?.name || s.player_id)}</b><span>${esc(s.position)}</span></div>`).join('')}</div>
</div>
${team.tactics && Object.keys(team.tactics).length ? `<div class="panel"><h2>How to set up</h2><div class="xi">${
  Object.entries(team.tactics).map(([k, v]) => `<div><b>${esc(v)}</b><span>${esc(k.replace(/_/g, ' '))}</span></div>`).join('')}</div></div>` : ''}
<div class="panel"><h2>Team SWOT</h2><div class="swot">${swotHtml(team.team_swot)}</div></div>
${team.position_weaknesses.length ? `<div class="panel"><h2>Where it hurts</h2>${
  team.position_weaknesses.map((w) => `<p class="weak"><b>${esc(w.area)}</b> — ${esc(w.issue)}</p>`).join('')}</div>` : ''}
<h2>Players</h2>
<div class="cards">${cards}</div>
